"""Proof of concept on AWS: deploy everything as ONE stack, test it, delete it all.

    uv run python scripts/poc.py up     --profile lyndev     # build, deploy, onboard LYNEAR
    uv run python scripts/poc.py smoke  --profile lyndev     # real documents through the real API
    uv run python scripts/poc.py status --profile lyndev
    uv run python scripts/poc.py down   --profile lyndev     # remove EVERYTHING

What exists in the AWS account while the POC runs:
  * stack `slm-poc`: ALL platform resources (generated by scripts/build_single_stack.py
    from the four normal templates; everything in it is deleted with the stack);
  * bucket `slm-poc-code-<account>-us-east-1`: the Lambda zip and the template file.
    It sits outside the stack because the code must be uploaded BEFORE the stack can
    create the functions. `down` deletes it too.

`down` also does what CloudFormation can't do alone:
  * empties the S3 buckets first (CloudFormation refuses to delete a non-empty bucket);
  * deletes the secrets IMMEDIATELY (otherwise Secrets Manager keeps them 30 days and
    the next `up` would fail on the name);
  * removes stray log groups, resets the API Gateway logging-role setting, and deletes
    the test page settings (tools/poc_ui/config.local.js, which holds the API key).
KMS keys can't be deleted at once by anyone: AWS deletes them after 7 days (~USD 0.25 each).

Region is always us-east-1 (architecture §3.4).
"""

from __future__ import annotations

import argparse
import importlib.util
import json
import os
import sys
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

REGION = "us-east-1"
STACK = "slm-poc"
ENV = "poc"
TENANT_NAME = "LYNEAR"
UI_DIR = ROOT / "tools" / "poc_ui"
UI_CONFIG = UI_DIR / "config.local.js"     # API URL + key for the browser test page (gitignored)
UI_SAMPLES = UI_DIR / "samples.js"         # synthetic sample documents for the page (gitignored)


def read_ui_config() -> dict:
    """config.local.js is `window.SLM_CONFIG = {...};`; return the {...} part."""
    if not UI_CONFIG.exists():
        return {}
    text = UI_CONFIG.read_text()
    return json.loads(text[text.index("{"): text.rindex("}") + 1])


def write_ui_files(api_url: str, api_key: str) -> None:
    """Settings + sample documents for tools/poc_ui/index.html, which runs straight from disk.

    The page can't read files or call Python, so both are written as small JS files it
    loads with <script>. The key file is readable by you only and is in .gitignore.
    """
    import base64

    from tests.helpers.sample_docs import make_invoice_png, make_statement_pdf

    UI_DIR.mkdir(parents=True, exist_ok=True)
    UI_CONFIG.write_text("// Written by scripts/poc.py up. Holds an API key: never commit or share this file.\n"
                         f"window.SLM_CONFIG = {json.dumps({'apiUrl': api_url, 'apiKey': api_key, 'tenant': TENANT_NAME})};\n")
    UI_CONFIG.chmod(0o600)
    samples = {"invoice.png": ("image/png", make_invoice_png()),
               "statement.pdf": ("application/pdf", make_statement_pdf())}
    UI_SAMPLES.write_text("// SYNTHETIC sample documents (tests/helpers/sample_docs.py). Written by scripts/poc.py up.\n"
                          "window.SLM_SAMPLES = " + json.dumps(
                              {name: {"type": ctype, "base64": base64.b64encode(data).decode()}
                               for name, (ctype, data) in samples.items()}) + ";\n")
    print(f"Wrote {UI_CONFIG.relative_to(ROOT)} and {UI_SAMPLES.relative_to(ROOT)} for the test page")


def _load_script(name: str):
    spec = importlib.util.spec_from_file_location(name, ROOT / "scripts" / f"{name}.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


# ---------------------------------------------------------------------------------------
# AWS session and small helpers
# ---------------------------------------------------------------------------------------

def _prefer_ipv4() -> None:
    """Make this LOCAL script connect to AWS over IPv4.

    Some AWS endpoints (e.g. Secrets Manager) also publish IPv6 addresses. On a network
    where IPv6 is broken, Python's HTTP library tries IPv6 first and hangs until a long
    timeout instead of falling back quickly. Forcing IPv4 here avoids that. It only
    affects this script on your machine, never the Lambda functions in AWS.
    """
    import socket

    import urllib3.util.connection as urllib3_connection

    urllib3_connection.allowed_gai_family = lambda: socket.AF_INET


def session_for(profile: str | None):
    import boto3

    _prefer_ipv4()

    if profile:
        os.environ["AWS_PROFILE"] = profile      # the app's own boto3 code (tenant script) uses it too
    os.environ["AWS_REGION"] = os.environ["AWS_DEFAULT_REGION"] = REGION
    sess = boto3.Session(profile_name=profile, region_name=REGION)
    ident = sess.client("sts").get_caller_identity()
    print(f"AWS account {ident['Account']}  as {ident['Arn'].split('/')[-1]}  region {REGION}")
    return sess, ident["Account"]


def code_bucket_name(account: str) -> str:
    return f"slm-{ENV}-code-{account}-{REGION}"


def stack_outputs(cfn) -> dict:
    try:
        stack = cfn.describe_stacks(StackName=STACK)["Stacks"][0]
    except cfn.exceptions.ClientError:
        return {}
    return {o["OutputKey"]: o["OutputValue"] for o in stack.get("Outputs", [])}


def stack_status(cfn) -> str | None:
    try:
        return cfn.describe_stacks(StackName=STACK)["Stacks"][0]["StackStatus"]
    except cfn.exceptions.ClientError:
        return None


def confirm(question: str, assume_yes: bool) -> bool:
    if assume_yes:
        return True
    return input(f"{question} [y/N] ").strip().lower() == "y"


def empty_bucket(s3, bucket: str) -> int:
    """Delete every object (and old version, if any) so CloudFormation can delete the bucket."""
    deleted = 0
    try:
        for page in s3.get_paginator("list_object_versions").paginate(Bucket=bucket):
            objs = [{"Key": o["Key"], "VersionId": o["VersionId"]}
                    for o in page.get("Versions", []) + page.get("DeleteMarkers", [])]
            for i in range(0, len(objs), 1000):
                s3.delete_objects(Bucket=bucket, Delete={"Objects": objs[i:i + 1000], "Quiet": True})
                deleted += len(objs[i:i + 1000])
    except s3.exceptions.NoSuchBucket:
        pass
    return deleted


def print_failures(cfn) -> None:
    """Show the first errors of a failed deployment: the real cause is usually the first one."""
    events = cfn.describe_stack_events(StackName=STACK)["StackEvents"]
    failed = [e for e in events if e["ResourceStatus"].endswith("FAILED")]
    for e in reversed(failed[-8:]):
        print(f"  ✗ {e['LogicalResourceId']} ({e['ResourceType']}): {e.get('ResourceStatusReason', '')}")


# ---------------------------------------------------------------------------------------
# up
# ---------------------------------------------------------------------------------------

def ensure_code_bucket(s3, bucket: str) -> None:
    try:
        s3.head_bucket(Bucket=bucket)
        return
    except s3.exceptions.ClientError:
        pass
    print(f"Creating code bucket {bucket}")
    s3.create_bucket(Bucket=bucket)                     # us-east-1: no LocationConstraint
    s3.put_public_access_block(Bucket=bucket, PublicAccessBlockConfiguration={
        "BlockPublicAcls": True, "IgnorePublicAcls": True, "BlockPublicPolicy": True, "RestrictPublicBuckets": True})
    s3.put_bucket_ownership_controls(Bucket=bucket, OwnershipControls={"Rules": [{"ObjectOwnership": "BucketOwnerEnforced"}]})
    s3.put_bucket_tagging(Bucket=bucket, Tagging={"TagSet": [{"Key": "app", "Value": "slm"}, {"Key": "env", "Value": ENV}]})


def upload_once(s3, bucket: str, key: str, path: Path) -> None:
    try:
        s3.head_object(Bucket=bucket, Key=key)
        print(f"  s3://{bucket}/{key} already uploaded")
    except s3.exceptions.ClientError:
        print(f"  uploading {path.name} ({path.stat().st_size / 1e6:.1f} MB)")
        s3.upload_file(str(path), bucket, key)


def deploy_stack(cfn, bucket: str, code_key: str, template_key: str, assume_yes: bool) -> bool:
    exists = stack_status(cfn) not in (None, "REVIEW_IN_PROGRESS")
    if stack_status(cfn) == "ROLLBACK_COMPLETE":
        # A first deployment that failed leaves a dead stack that can only be deleted.
        print("Previous first deployment failed (ROLLBACK_COMPLETE): deleting it before retrying.")
        cfn.delete_stack(StackName=STACK)
        cfn.get_waiter("stack_delete_complete").wait(StackName=STACK)
        exists = False

    name = f"poc-{int(time.time())}"
    cfn.create_change_set(
        StackName=STACK, ChangeSetName=name, ChangeSetType="UPDATE" if exists else "CREATE",
        TemplateURL=f"https://{bucket}.s3.{REGION}.amazonaws.com/{template_key}",
        Parameters=[{"ParameterKey": "CodeBucketName", "ParameterValue": bucket},
                    {"ParameterKey": "CodeKey", "ParameterValue": code_key}],
        Capabilities=["CAPABILITY_NAMED_IAM"],
        Tags=[{"Key": "app", "Value": "slm"}, {"Key": "env", "Value": ENV},
              {"Key": "purpose", "Value": "proof-of-concept"}],
    )
    try:
        cfn.get_waiter("change_set_create_complete").wait(
            StackName=STACK, ChangeSetName=name, WaiterConfig={"Delay": 5, "MaxAttempts": 120})
    except Exception:
        cs = cfn.describe_change_set(StackName=STACK, ChangeSetName=name)
        if "didn't contain changes" in cs.get("StatusReason", "") or "No updates" in cs.get("StatusReason", ""):
            print("Stack is already up to date.")
            cfn.delete_change_set(StackName=STACK, ChangeSetName=name)
            return True
        print(f"Change set failed: {cs.get('StatusReason')}")
        return False

    changes, token = [], None
    while True:
        kw = {"StackName": STACK, "ChangeSetName": name, **({"NextToken": token} if token else {})}
        cs = cfn.describe_change_set(**kw)
        changes += [c["ResourceChange"] for c in cs["Changes"]]
        token = cs.get("NextToken")
        if not token:
            break
    summary: dict[str, int] = {}
    for c in changes:
        summary[c["Action"]] = summary.get(c["Action"], 0) + 1
    replaced = [c["LogicalResourceId"] for c in changes if c.get("Replacement") == "True"]
    print(f"Planned changes: {summary}" + (f"  REPLACED (deleted and recreated): {replaced}" if replaced else ""))
    if not confirm(f"Execute change set {name} on stack {STACK}?", assume_yes):
        print("Not executed. The change set is kept for review in the CloudFormation console.")
        return False

    cfn.execute_change_set(StackName=STACK, ChangeSetName=name)
    print("Deploying (first time ~5-8 minutes) ...")
    waiter = cfn.get_waiter("stack_update_complete" if exists else "stack_create_complete")
    try:
        waiter.wait(StackName=STACK, WaiterConfig={"Delay": 15, "MaxAttempts": 160})
    except Exception:
        print(f"Deployment FAILED, stack status: {stack_status(cfn)}")
        print_failures(cfn)
        return False
    print(f"Stack {STACK}: {stack_status(cfn)}")
    return True


def ensure_api_key(outputs: dict) -> str:
    """Make sure LYNEAR exists and the local test app has a working API key."""
    import httpx

    api_url = outputs["ApiUrl"].rstrip("/")
    saved = read_ui_config()
    if saved.get("apiUrl") == api_url and saved.get("apiKey"):
        r = httpx.get(f"{api_url}/v1/document-types",
                      headers={"Authorization": f"Bearer {saved['apiKey']}"}, timeout=30)
        if r.status_code == 200:
            print(f"Test page settings already valid ({UI_CONFIG.relative_to(ROOT)})")
            write_ui_files(api_url, saved["apiKey"])     # refresh the samples
            return saved["apiKey"]

    tenant_script = _load_script("create_tenant")
    tenant_script.configure_environment(ENV)     # SLM_* names of the poc resources, BEFORE importing app
    from app.storage.aws import dynamodb_table
    from app.storage.tenants import create_api_key

    existing = dynamodb_table().get_item(
        Key={"PK": f"TENANTNAME#{TENANT_NAME.lower()}", "SK": "TENANTNAME"}).get("Item")
    if existing:
        api_key = create_api_key(existing["tenant_id"], ["extractions:read", "extractions:write"], live=False)
        print(f"Tenant {TENANT_NAME} exists ({existing['tenant_id']}): created a new API key for the test app.")
    else:
        api_key = tenant_script.main(["--env", ENV, "--name", TENANT_NAME])["api_key"]

    write_ui_files(api_url, api_key)
    return api_key


def cmd_up(args) -> int:
    sess, account = session_for(args.profile)
    s3, cfn = sess.client("s3"), sess.client("cloudformation")
    bucket = code_bucket_name(account)

    print("1/5 Building the Lambda package")
    zip_path = _load_script("build_lambda").build()
    print("2/5 Generating the single-stack template")
    template = _load_script("build_single_stack").build()

    print("3/5 Uploading")
    ensure_code_bucket(s3, bucket)
    upload_once(s3, bucket, f"code/{zip_path.name}", zip_path)
    template_key = f"templates/slm-poc-{int(time.time())}.json"
    s3.upload_file(str(template), bucket, template_key)

    print("4/5 Deploying the stack")
    if not deploy_stack(cfn, bucket, f"code/{zip_path.name}", template_key, args.yes):
        return 1

    print("5/5 Onboarding the first tenant and configuring the local test app")
    outputs = stack_outputs(cfn)
    ensure_api_key(outputs)
    print(f"\nAPI: {outputs['ApiUrl']}")
    print("Next:  uv run python scripts/poc.py smoke --profile <profile>")
    print(f"       open {UI_DIR.relative_to(ROOT)}/index.html in your browser (no server needed)")
    return 0


# ---------------------------------------------------------------------------------------
# smoke: real documents through the deployed API
# ---------------------------------------------------------------------------------------

def cmd_smoke(args) -> int:
    import httpx

    from tests.helpers.sample_docs import make_invoice_png, make_statement_pdf

    sess, _ = session_for(args.profile)
    outputs = stack_outputs(sess.client("cloudformation"))
    if not outputs:
        print("Stack not deployed. Run `up` first.")
        return 1
    api = outputs["ApiUrl"].rstrip("/")
    auth = {"Authorization": f"Bearer {read_ui_config()['apiKey']}"}
    ok = True

    def check(label: str, cond: bool, detail: str = "") -> None:
        nonlocal ok
        ok &= cond
        print(f"  {'✓' if cond else '✗'} {label}{(': ' + detail) if detail else ''}")

    def wait_final(job_id: str, limit_s: int = 180) -> dict:
        deadline = time.monotonic() + limit_s
        while True:
            body = httpx.get(f"{api}/v1/extractions/{job_id}?wait=20", headers=auth, timeout=40).json()
            if body["status"] in ("succeeded", "failed", "expired") or time.monotonic() > deadline:
                return body

    print("1. Health and authentication")
    check("GET /healthz", httpx.get(f"{api}/healthz", timeout=30).json() == {"ok": True})
    check("no key -> 401", httpx.get(f"{api}/v1/extractions", timeout=30).status_code == 401)
    check("LYNEAR key -> 200", httpx.get(f"{api}/v1/document-types", headers=auth, timeout=30).status_code == 200)

    print("2. Direct flow: digital bank statement (multipart) -> Rung 0 parser + Nova Lite check")
    t0 = time.monotonic()
    r = httpx.post(f"{api}/v1/extractions?wait=25", headers=auth, timeout=40,
                   # A unique account number per run, so duplicate detection doesn't just
                   # return the previous run's result.
                   files={"file": ("statement.pdf", make_statement_pdf(account=f"0012{int(time.time()) % 10**8:08d}"),
                                   "application/pdf")})
    body = r.json() if r.status_code in (200, 202) else {"status": f"HTTP {r.status_code}", "raw": r.text[:300]}
    if body.get("status") not in ("succeeded", "failed") and "id" in body:
        body = wait_final(body["id"])
    check("statement extracted", body.get("status") == "succeeded",
          f"{body.get('status')} method={body.get('method')} parser={body.get('parser_id')} "
          f"verified_by={body.get('verified_by')} error={body.get('error')} in {time.monotonic() - t0:.1f}s")
    if body.get("result"):
        res = body["result"]
        check("12 transactions, closing balance and masked account",
              len(res.get("transactions", [])) == 12 and res.get("account_number", "").startswith("XXXX"),
              f"closing={res.get('closing_balance')} account={res.get('account_number')}")

    print("3. Presigned flow: scanned invoice image -> GuardDuty scan -> AI ladder (Claude Haiku 5.5)")
    t0 = time.monotonic()
    created = httpx.post(f"{api}/v1/extractions", headers=auth, json={"document_type": "invoice"}, timeout=30).json()
    up = created["upload"]
    s3r = httpx.post(up["url"], data=up["fields"], files={"file": ("invoice.png", make_invoice_png(), "image/png")},
                     timeout=60)
    check("upload to S3", s3r.status_code in (200, 204), f"HTTP {s3r.status_code}")
    body = wait_final(created["id"])
    check("invoice extracted", body.get("status") == "succeeded",
          f"{body.get('status')} model={body.get('model_id')} warnings={body.get('warnings')} "
          f"error={body.get('error')} in {time.monotonic() - t0:.1f}s")
    if body.get("result"):
        res = body["result"]
        check("totals and masked PAN", res.get("total") == "17700.00"
              and ((res.get("seller") or {}).get("pan") or "").startswith("XXXX"),
              f"invoice={res.get('invoice_number')} total={res.get('total')} pan={(res.get('seller') or {}).get('pan')}")

    print("\nALL CHECKS PASSED" if ok else "\nSOME CHECKS FAILED (see the worker logs: "
          f"aws logs tail /aws/lambda/slm-{ENV}-worker --since 15m --profile <profile> --region {REGION})")
    return 0 if ok else 1


# ---------------------------------------------------------------------------------------
# status and down
# ---------------------------------------------------------------------------------------

def cmd_status(args) -> int:
    sess, account = session_for(args.profile)
    cfn = sess.client("cloudformation")
    print(f"Stack {STACK}: {stack_status(cfn) or 'not deployed'}")
    for k, v in stack_outputs(cfn).items():
        print(f"  {k:22s} {v}")
    print(f"Code bucket: {code_bucket_name(account)}")
    print(f"Test page settings: {'present' if UI_CONFIG.exists() else 'missing'} ({UI_CONFIG.relative_to(ROOT)})")
    return 0


def cmd_down(args) -> int:
    sess, account = session_for(args.profile)
    cfn, s3, sm, logs = (sess.client(n) for n in ("cloudformation", "s3", "secretsmanager", "logs"))
    if not args.yes:
        answer = input(f"This deletes ALL proof-of-concept resources and data in account {account}.\n"
                       f"Type the stack name ({STACK}) to continue: ")
        if answer.strip() != STACK:
            print("Cancelled.")
            return 1

    outputs = stack_outputs(cfn)
    docs_bucket = f"slm-{ENV}-docs-{account}-{REGION}"
    print(f"1/6 Emptying {docs_bucket}: {empty_bucket(s3, docs_bucket)} objects deleted")

    print("2/6 Deleting secrets immediately (no 30-day recovery window)")
    names = [s["Name"] for p in sm.get_paginator("list_secrets").paginate(
        Filters=[{"Key": "name", "Values": [f"slm/{ENV}/"]}]) for s in p["SecretList"]]
    for name in names:
        sm.delete_secret(SecretId=name, ForceDeleteWithoutRecovery=True)
        print(f"  deleted {name}")

    if stack_status(cfn):
        print(f"3/6 Deleting stack {STACK} (~5 minutes)")
        for attempt in (1, 2):
            cfn.delete_stack(StackName=STACK)
            try:
                cfn.get_waiter("stack_delete_complete").wait(StackName=STACK, WaiterConfig={"Delay": 15, "MaxAttempts": 160})
                break
            except Exception:
                print(f"  delete attempt {attempt} failed:")
                print_failures(cfn)
                empty_bucket(s3, docs_bucket)    # e.g. a file arrived while deleting
                if attempt == 2:
                    return 1
    else:
        print("3/6 Stack already deleted")

    bucket = code_bucket_name(account)
    print(f"4/6 Deleting code bucket {bucket}")
    empty_bucket(s3, bucket)
    try:
        s3.delete_bucket(Bucket=bucket)
    except s3.exceptions.ClientError as e:
        if "NoSuchBucket" not in str(e):
            raise

    print("5/6 Removing leftovers: stray log groups, API Gateway logging-role setting")
    for prefix in (f"/aws/lambda/slm-{ENV}-", f"/aws/apigateway/slm-{ENV}-"):
        for p in logs.get_paginator("describe_log_groups").paginate(logGroupNamePrefix=prefix):
            for g in p["logGroups"]:
                logs.delete_log_group(logGroupName=g["logGroupName"])
                print(f"  deleted log group {g['logGroupName']}")
    apigw = sess.client("apigateway")
    if f"slm-{ENV}-apigateway-logs" in (apigw.get_account().get("cloudwatchRoleArn") or ""):
        try:   # the role was deleted with the stack; don't leave the account pointing at it
            apigw.update_account(patchOperations=[{"op": "replace", "path": "/cloudwatchRoleArn", "value": ""}])
            print("  reset API Gateway account logging role")
        except apigw.exceptions.ClientError as e:
            print(f"  (could not reset API Gateway logging role: {e.response['Error']['Message']})")

    print("6/6 Removing the local test app settings")
    UI_CONFIG.unlink(missing_ok=True)
    UI_SAMPLES.unlink(missing_ok=True)
    print(f"\nDone. Everything is deleted except the 3 KMS keys, which AWS deletes automatically after "
          f"7 days (~USD 0.25 in total). Outputs that existed: {', '.join(outputs) or 'none'}")
    return 0


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description="Deploy, test and remove the single-stack proof of concept.")
    p.add_argument("command", choices=["up", "smoke", "status", "down"])
    p.add_argument("--profile", help="AWS CLI profile, e.g. lyndev")
    p.add_argument("--yes", action="store_true", help="Don't ask before executing (up: change set; down: deletion)")
    args = p.parse_args(argv)
    return {"up": cmd_up, "smoke": cmd_smoke, "status": cmd_status, "down": cmd_down}[args.command](args)


if __name__ == "__main__":
    sys.exit(main())
